import{_ as a,o as i,c as t,ag as e}from"./chunks/framework.7He2WLS4.js";const k=JSON.parse('{"title":"nectoproxy start","description":"","frontmatter":{},"headers":[],"relativePath":"cli/start.md","filePath":"cli/start.md","lastUpdated":1772297611000}'),n={name:"cli/start.md"};function o(l,s,p,h,r,d){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="nectoproxy-start" tabindex="-1">nectoproxy start <a class="header-anchor" href="#nectoproxy-start" aria-label="Permalink to &quot;nectoproxy start&quot;">​</a></h1><p>The <code>start</code> command launches the NectoProxy proxy server and Web UI. This is the primary command you will use.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options]</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Alias</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--port &lt;port&gt;</code></td><td><code>-p</code></td><td><code>8888</code></td><td>Port for the HTTP/HTTPS proxy server</td></tr><tr><td><code>--ui-port &lt;port&gt;</code></td><td><code>-u</code></td><td><code>8889</code></td><td>Port for the Web UI dashboard</td></tr><tr><td><code>--host &lt;host&gt;</code></td><td></td><td><code>127.0.0.1</code></td><td>Host address to bind to</td></tr><tr><td><code>--no-open</code></td><td></td><td></td><td>Do not automatically open the Web UI in the default browser</td></tr></tbody></table><h2 id="default-behavior" tabindex="-1">Default Behavior <a class="header-anchor" href="#default-behavior" aria-label="Permalink to &quot;Default Behavior&quot;">​</a></h2><p>When you run <code>nectoproxy start</code> without any options:</p><ol><li>The <strong>proxy server</strong> starts on <code>127.0.0.1:8888</code>.</li><li>The <strong>Web UI</strong> starts on <code>127.0.0.1:8889</code>.</li><li>Your <strong>default browser</strong> opens automatically to the Web UI URL.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  NectoProxy v0.1.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Proxy server running on http://127.0.0.1:8888</span></span>
<span class="line"><span>  Web UI available at  http://127.0.0.1:8889</span></span></code></pre></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="basic-start" tabindex="-1">Basic Start <a class="header-anchor" href="#basic-start" aria-label="Permalink to &quot;Basic Start&quot;">​</a></h3><p>Start NectoProxy with all defaults:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h3 id="custom-ports" tabindex="-1">Custom Ports <a class="header-anchor" href="#custom-ports" aria-label="Permalink to &quot;Custom Ports&quot;">​</a></h3><p>Use different ports for the proxy and Web UI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9090</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9091</span></span></code></pre></div><p>This starts:</p><ul><li>Proxy on <code>127.0.0.1:9090</code></li><li>Web UI on <code>127.0.0.1:9091</code></li></ul><div class="tip custom-block"><p class="custom-block-title">When to Change Ports</p><p>Change the default ports when:</p><ul><li>Port 8888 or 8889 is already in use by another application.</li><li>You need to run multiple NectoProxy instances simultaneously.</li><li>Your organization has port allocation policies.</li></ul></div><h3 id="lan-access-debug-mobile-devices" tabindex="-1">LAN Access (Debug Mobile Devices) <a class="header-anchor" href="#lan-access-debug-mobile-devices" aria-label="Permalink to &quot;LAN Access (Debug Mobile Devices)&quot;">​</a></h3><p>To allow connections from other devices on your local network (e.g., mobile phones, tablets, or other computers), bind to all network interfaces:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p>This makes the proxy accessible at <code>&lt;your-lan-ip&gt;:8888</code> and the Web UI at <code>&lt;your-lan-ip&gt;:8889</code> from any device on the same network.</p><div class="warning custom-block"><p class="custom-block-title">Security Consideration</p><p>Binding to <code>0.0.0.0</code> exposes NectoProxy to your entire local network. Only use this on trusted networks. Anyone on the network can route their traffic through your proxy and access the Web UI.</p></div><h3 id="without-auto-opening-browser" tabindex="-1">Without Auto-Opening Browser <a class="header-anchor" href="#without-auto-opening-browser" aria-label="Permalink to &quot;Without Auto-Opening Browser&quot;">​</a></h3><p>If you do not want the browser to open automatically when starting NectoProxy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span></code></pre></div><p>This is useful when:</p><ul><li>Running NectoProxy on a headless server or remote machine.</li><li>You prefer to open the Web UI manually.</li><li>You are running NectoProxy in a script or automated workflow.</li></ul><h3 id="combined-options" tabindex="-1">Combined Options <a class="header-anchor" href="#combined-options" aria-label="Permalink to &quot;Combined Options&quot;">​</a></h3><p>You can combine all options:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9090</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9091</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span></code></pre></div><p>This starts the proxy on port 9090, the Web UI on port 9091, listens on all interfaces, and does not open the browser.</p><h2 id="stopping-nectoproxy" tabindex="-1">Stopping NectoProxy <a class="header-anchor" href="#stopping-nectoproxy" aria-label="Permalink to &quot;Stopping NectoProxy&quot;">​</a></h2><p>NectoProxy runs in the foreground in your terminal. To stop it:</p><ul><li>Press <code>Ctrl+C</code> in the terminal where NectoProxy is running.</li></ul><p>NectoProxy performs a graceful shutdown, closing active connections and saving any pending data to the database.</p><details class="details custom-block"><summary>Running in the Background</summary><p>If you want NectoProxy to run in the background, you can use standard process management tools:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Using nohup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nohup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Using screen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dmS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Using tmux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-session</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nectoproxy start --no-open&#39;</span></span></code></pre></div><p>Use <code>Ctrl+C</code> or <code>kill</code> the process to stop it when running in the background.</p></details><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="port-already-in-use" tabindex="-1">Port Already in Use <a class="header-anchor" href="#port-already-in-use" aria-label="Permalink to &quot;Port Already in Use&quot;">​</a></h3><p>If you see an error like <code>EADDRINUSE: address already in use</code>:</p><ol><li><p>Check what is using the port:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS / Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :8888</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ano</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> findstr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :8888</span></span></code></pre></div></li><li><p>Either stop the conflicting application or use a different port:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9090</span></span></code></pre></div></li></ol><h3 id="permission-denied-on-port" tabindex="-1">Permission Denied on Port <a class="header-anchor" href="#permission-denied-on-port" aria-label="Permalink to &quot;Permission Denied on Port&quot;">​</a></h3><p>On macOS and Linux, ports below 1024 require root privileges. NectoProxy&#39;s default ports (8888 and 8889) do not require elevated permissions. If you attempt to use a low port number, you will need <code>sudo</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 443</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Avoid Running as Root</p><p>Running NectoProxy as root is generally not recommended. Use the default ports or any port above 1024 instead.</p></div>`,49)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
